#include <cstddef>
#include <mutex>
#include <vector>

class Bank
{
public:
    Bank(std::size_t accounts, long long startingBalance);
    bool transfer(std::size_t from, std::size_t to, long long amount);
    long long balance(std::size_t account) const;
    long long total() const;

private:
    struct Account
    {
        mutable std::mutex mutex{};
        long long balance{ 0 };
    };
    std::vector<Account> m_accounts;
};

Bank::Bank(std::size_t accounts, long long startingBalance) : m_accounts(accounts)
{
    for (Account& account : m_accounts)
    {
        account.balance = startingBalance;
    }
}

bool Bank::transfer(std::size_t from, std::size_t to, long long amount)
{
    if (from == to || amount <= 0)
    {
        return false;
    }
    Account& source{ m_accounts[from] };
    Account& target{ m_accounts[to] };
    const std::scoped_lock lock{ source.mutex, target.mutex };
    if (source.balance < amount)
    {
        return false;
    }
    source.balance -= amount;
    target.balance += amount;
    return true;
}

long long Bank::balance(std::size_t account) const
{
    const std::lock_guard lock{ m_accounts[account].mutex };
    return m_accounts[account].balance;
}

long long Bank::total() const
{
    long long sum{ 0 };
    for (const Account& account : m_accounts)
    {
        const std::lock_guard lock{ account.mutex };
        sum += account.balance;
    }
    return sum;
}

