#include <thread>
TEST("basic transfers") { Bank b{ 3, 100 }; CHECK(b.transfer(0, 1, 30)); CHECK_EQ(b.balance(0), 70); CHECK_EQ(b.balance(1), 130); CHECK_EQ(b.total(), 300); }
TEST("refused transfers change nothing") { Bank b{ 2, 50 }; CHECK(!b.transfer(0, 1, 51)); CHECK(!b.transfer(0, 0, 10)); CHECK(!b.transfer(0, 1, 0)); CHECK(!b.transfer(0, 1, -5)); CHECK_EQ(b.balance(0), 50); CHECK_EQ(b.balance(1), 50); }
TEST("opposite transfers on many threads: no deadlock, no money lost") {
    Bank b{ 4, 100000 };
    {
        std::vector<std::jthread> threads;
        for (int t{ 0 }; t < 8; ++t)
        {
            threads.emplace_back([&b, t] {
                for (int i{ 0 }; i < 20000; ++i)
                {
                    const std::size_t from{ static_cast<std::size_t>((t + i) % 4) };
                    const std::size_t to{ static_cast<std::size_t>((t + i * 3 + 1) % 4) };
                    b.transfer(from, to, 1 + (i % 7));
                }
            });
        }
    }
    CHECK_EQ(b.total(), 400000);
    for (std::size_t a{ 0 }; a < 4; ++a) CHECK(b.balance(a) >= 0);
}

